mapper.select:
SELECT mp.participant_id, u.nickname, mp.participation_status, mp.match_side, mp.joined_at FROM match_participant mp JOIN social_match sm ON sm.match_id = mp.match_id JOIN facility f ON f.facility_id = sm.facility_id AND f.deleted_at IS NULL JOIN facility_manager fm ON fm.facility_id = f.facility_id AND fm.user_id = #{managerUserId} JOIN app_user u ON u.user_id = mp.user_id WHERE mp.match_id = #{matchId} AND mp.participation_status IN
#{st}
ORDER BY mp.joined_at, mp.participant_id
